"""Clean vector coloring stencils, extending the existing SVG art library."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]

def make(index,body,details):
    svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 360">
<path id="body" fill="#fff" d="{body}"/>
<g id="ink" fill="none" stroke="#000" stroke-width="5" stroke-linecap="round" stroke-linejoin="round">
<path d="{body}"/>{details}</g></svg>'''
    (ROOT/f'art/paint/dino{index}.svg').write_text(svg+'\n')

